const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// Total orders & revenue
const totalOrders = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = data.reduce((s, r) => s + r['Total Paid'], 0);
const confirmedRevenue = confirmed.reduce((s, r) => s + r['Total Paid'], 0);
const cancelledRevenue = cancelled.reduce((s, r) => s + r['Total Paid'], 0);

// By customer
const byCust = {};
confirmed.forEach(r => {
  if (!byCust[r.Customer]) byCust[r.Customer] = { orders: 0, total: 0 };
  byCust[r.Customer].orders++;
  byCust[r.Customer].total += r['Total Paid'];
});
const topCustomers = Object.entries(byCust).sort((a,b) => b[1].total - a[1].total).slice(0, 5);

// Items frequency
const itemCount = {};
confirmed.forEach(r => {
  r.Items.split(', ').forEach(i => { itemCount[i] = (itemCount[i] || 0) + 1; });
});
const topItems = Object.entries(itemCount).sort((a,b) => b[1] - a[1]).slice(0, 5);

// Date range
const dates = [...new Set(data.map(r => r.Date))].sort();

let summary = 'ORDER SUMMARY REPORT\n';
summary += '====================\n\n';
summary += 'Date Range: ' + dates[0] + ' to ' + dates[dates.length-1] + '\n\n';
summary += '--- Overall ---\n';
summary += 'Total Orders: ' + totalOrders + '\n';
summary += '  Confirmed: ' + confirmed.length + '\n';
summary += '  Cancelled: ' + cancelled.length + '\n';
summary += 'Total Revenue (all orders): \$' + totalRevenue + '\n';
summary += 'Confirmed Revenue: \$' + confirmedRevenue + '\n';
summary += 'Cancelled Revenue: \$' + cancelledRevenue + '\n';
summary += 'Average Order Value (confirmed): \$' + (confirmedRevenue / confirmed.length).toFixed(2) + '\n\n';

summary += '--- Top 5 Customers by Confirmed Revenue ---\n';
topCustomers.forEach(([c, v]) => {
  summary += '  ' + c + ': ' + v.orders + ' orders, \$' + v.total + '\n';
});

summary += '\n--- Top 5 Most Ordered Items (confirmed) ---\n';
topItems.forEach(([item, count]) => {
  summary += '  ' + item + ': ' + count + ' orders\n';
});

console.log(summary);
"

