const fs = require('fs');
const path = require('path');

const TESTBED_DIR = '/workspace/testbed';
const sender = 'assistant';
const recipient = 'bob';
const subject = 'Order Summary Report';
const content = \`ORDER SUMMARY REPORT
====================

Date Range: 2026-09-02 to 2026-09-04

--- Overall ---
Total Orders: 27
  Confirmed: 24
  Cancelled: 3
Total Revenue (all orders): \\\$2017
Confirmed Revenue: \\\$1831
Cancelled Revenue: \\\$186
Average Order Value (confirmed): \\\$76.29

--- Top 5 Customers by Confirmed Revenue ---
  Maya Chen: 5 orders, \\\$477
  Evan Parker: 4 orders, \\\$276
  Alicia Morgan: 2 orders, \\\$137
  user_2f61840f: 1 orders, \\\$123
  Sofia Ramirez: 1 orders, \\\$120

--- Top 5 Most Ordered Items (confirmed) ---
  LogiTech Wireless Mouse M310: 13 orders
  OXO SoftWorks 3-Piece Mixing Bowl Set: 7 orders
  Everyday Canvas Tote Bag: 5 orders
  Bamboo Desk Organizer Set: 5 orders
  Levi's Classic Cotton T-Shirt: 4 orders\`;

// Build RFC 2822-style email
const now = new Date().toUTCString();
const email = [
  'From: ' + sender + '@example.com',
  'To: ' + recipient + '@example.com',
  'Subject: ' + subject,
  'Date: ' + now,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=\"utf-8\"',
  '',
  content
].join('\r\n');

for (const folder of [sender, recipient]) {
  const dir = path.join(TESTBED_DIR, 'emails', folder);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, subject + '.eml'), email);
}
console.log('Successfully sent email to ' + recipient + '@example.com');
"
